SELECT v.rol_id, v.rol_nombre, v.rol_description, TRUE, NOW(), 'flyway'
  FROM (
    VALUES
      (1, 'SITEC-Administrador', NULL),
      (2, 'SITEC-Tecnico', NULL),
      (3, 'SITEC-Analista', NULL),
      (4, 'SITEC-Tribunal', 'Tribunal Electoral (cronograma, resoluciones)'),
