      (6, 'SITEC-Presidente-mesa', 'Presidente de mesa electoral')
  ) AS v(rol_id, rol_nombre, rol_description)
 WHERE NOT EXISTS (
     SELECT 1
       FROM public.tb_rol r
      WHERE r.rol_id = v.rol_id
         OR r.rol_nombre = v.rol_nombre
 );

SELECT setval(
    pg_get_serial_sequence('public.tb_rol', 'rol_id'),
    GREATEST((SELECT COALESCE(MAX(rol_id), 1) FROM public.tb_rol), 1),
    TRUE
);

